from pathlib import Path
import base64
root=Path(__file__).resolve().parent.parent
out=root/'conceitos'
def font(n): return base64.b64encode((root/'assets/fonts'/n).read_bytes()).decode()
css='''
:root{--bg:#0b1413;--panel:#142321;--line:#2c4240;--mint:#39f59a;--text:#edf6f1;--muted:#a1b9b2;--ease:cubic-bezier(.2,0,0,1)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Jakarta,system-ui,sans-serif;font-size:14px}button,input,select,textarea{font:inherit}button,a,input,textarea,select{outline-offset:5px}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--mint)}button{cursor:pointer;color:inherit;transition:transform 160ms var(--ease),background 160ms var(--ease)}button:active{transform:scale(.97)}button:hover{background:#29453c}a{color:inherit}h1,h2,h3,p{margin-top:0}h1,h2,h3{font-family:Space,system-ui,sans-serif}h1{font-size:clamp(34px,4.5vw,64px);line-height:1.08;letter-spacing:-2px;margin-bottom:18px}h2{font-size:25px}h3{font-size:19px}p{line-height:1.7;color:var(--muted)}.lab{position:sticky;top:0;z-index:10;background:#21352d;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 24px;border-bottom:1px solid var(--line);font-size:11px}.lab strong{color:var(--mint)}.quiet{border:1px solid var(--line);background:transparent;border-radius:9px;padding:10px 14px}.layout{display:grid;grid-template-columns:230px minmax(0,1fr)}aside{position:sticky;top:52px;height:calc(100dvh - 52px);padding:28px 15px;border-right:1px solid var(--line);overflow-y:auto}.brand{display:flex;gap:12px;align-items:center;margin:0 12px 26px;font-family:Space;font-size:25px}.brand img{width:36px;height:36px;object-fit:contain}.group{font-size:10px;letter-spacing:2px;color:var(--muted);padding:18px 14px 7px;text-transform:uppercase}nav a{display:flex;text-decoration:none;padding:10px 13px;border-radius:9px;gap:12px;color:var(--muted);margin-bottom:3px;font-size:12px;align-items:center}nav a:hover{background:var(--panel);color:var(--text)}nav a[aria-current=page]{background:var(--mint);color:#082218}.nav-icon{font-size:18px;width:22px;text-align:center}main{min-width:0;padding:28px 42px 50px;max-width:1600px}.topline{display:flex;justify-content:space-between;align-items:center;margin-bottom:40px;gap:12px;color:var(--muted);font-size:12px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:2px;color:var(--mint);display:block;margin-bottom:18px}.intro{max-width:650px}.intro p{max-width:540px;font-size:15px}.concept{margin-bottom:70px}.js .concept{display:none}.js .concept.active{display:block;animation:arrive 440ms var(--ease)}@keyframes arrive{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}.split{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(260px,.8fr);gap:24px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:24px;min-width:0}.hero{background:#173b2b;border-color:#37604a;padding:30px}.primary{background:var(--mint);color:#09291b;border:0;border-radius:10px;font-weight:700;padding:13px 19px}.primary:hover{background:#86ffbf}.row{display:flex;align-items:center;justify-content:space-between;gap:14px}.tag{display:inline-block;border:1px solid var(--line);padding:5px 9px;border-radius:7px;font-size:10px;color:var(--muted)}.mint{color:var(--mint)}.small{font-size:12px}.muted{color:var(--muted)}.num{font-family:Space;font-size:40px;letter-spacing:-1px}.track{height:6px;border-radius:5px;background:#263d35;overflow:hidden;margin-top:14px}.track span{display:block;height:100%;background:var(--mint);border-radius:5px;transition:width 450ms var(--ease)}.task{display:flex;align-items:center;gap:15px;padding:17px 0;border-bottom:1px solid var(--line)}.task input{accent-color:var(--mint);width:18px;height:18px}.task:has(input:checked) span{text-decoration:line-through;color:var(--muted)}.task em{margin-left:auto;font-size:11px;color:var(--muted);font-style:normal}.map{position:relative;min-height:325px;overflow:hidden;display:grid;place-items:center;background:radial-gradient(ellipse at center,#204c3b 0,transparent 65%)}.map:before,.map:after{content:'';position:absolute;border:1px solid #39f59a30;border-radius:50%;width:230px;height:230px;pointer-events:none}.map:after{width:330px;height:330px;animation:breathe 8s ease-in-out infinite}.core{text-align:center;padding:12px;background:var(--mint);color:#082218;width:96px;height:96px;border-radius:50%;display:grid;place-items:center;font-family:Space;font-size:19px}.node{position:absolute;border:1px solid #476859;background:#122c22;border-radius:12px;padding:12px 15px}.node:nth-of-type(1){left:6%;top:17%}.node:nth-of-type(2){right:5%;top:28%}.node:nth-of-type(3){left:15%;bottom:14%}.node:nth-of-type(4){right:10%;bottom:10%}@keyframes breathe{50%{transform:scale(1.035);opacity:.5}}.notes{margin-top:30px;border-top:1px solid var(--line);padding-top:18px;display:grid;grid-template-columns:1.5fr 1fr;gap:30px}.notes p{font-size:12px;margin-bottom:5px}.notes b{color:var(--text)}.week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;margin:25px 0}.day{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 5px;text-align:center}.day strong{display:block;font-family:Space;font-size:25px;margin:12px 0}.day.selected{border-color:var(--mint);background:#224131}.day small{color:var(--muted);font-size:10px}.dot{height:5px;width:5px;background:var(--mint);display:inline-block;border-radius:50%}.ring{--progress:0%;width:270px;height:270px;border-radius:50%;background:conic-gradient(var(--mint) var(--progress),#284238 0);padding:4px;display:grid;place-items:center;margin:30px auto;position:relative}.ring:before{content:'';position:absolute;inset:-18px;border:1px dashed #365244;border-radius:50%}.ring-inner{background:var(--bg);border-radius:50%;width:100%;height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column}.timer{font-family:Space;font-size:62px;font-variant-numeric:tabular-nums;letter-spacing:-3px}.center{text-align:center}.seg{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.seg button{border:1px solid var(--line);background:transparent;padding:10px 16px;border-radius:9px}.seg button.selected{color:#09291b;background:var(--mint);border-color:var(--mint)}.bars{height:230px;display:flex;align-items:end;gap:16px;padding-top:20px}.bar-col{flex:1;height:100%;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:10px}.bar{background:var(--mint);width:75%;border-radius:7px 7px 0 0;transition:height 500ms var(--ease);min-height:5px}.heatmap{display:grid;grid-template-columns:repeat(14,1fr);gap:6px;margin-top:20px}.heatmap span{aspect-ratio:1;background:#20382e;border-radius:3px}.heatmap span:nth-child(3n){background:#268356}.heatmap span:nth-child(5n){background:var(--mint)}.podium{display:flex;align-items:end;justify-content:center;gap:16px;min-height:280px;padding:20px 0}.podium>div{width:26%;background:#1e3a31;border-top:2px solid #476658;padding:24px 10px;text-align:center;border-radius:14px 14px 0 0}.podium>div:nth-child(2){background:#214d34;border-color:var(--mint);padding-top:58px}.avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#36473f;color:var(--mint);margin:0 auto 12px;font-family:Space;font-size:18px}.podium .num{display:block}.chat{min-height:290px;display:flex;flex-direction:column;justify-content:center;gap:18px}.bubble{background:#213e32;align-self:flex-end;padding:16px 20px;border-radius:16px 16px 3px 16px;max-width:85%;line-height:1.6}.reply{padding:20px;border-left:2px solid var(--mint);max-width:90%;line-height:1.8}.composer{display:flex;align-items:end;gap:10px;border:1px solid #496154;border-radius:16px;padding:12px;background:#0f2019}.composer textarea{flex:1;resize:vertical;min-width:0;border:0;background:none;color:var(--text);padding:10px}.form label{display:block;color:var(--muted);font-size:12px;margin:18px 0 8px}input:not([type=checkbox]):not([type=range]),select,textarea.field{width:100%;border:1px solid var(--line);background:#0d1a16;color:var(--text);border-radius:10px;padding:13px}input[type=range]{accent-color:var(--mint);width:100%}.art{height:140px;display:grid;place-items:center;margin:-24px -24px 24px;border-radius:17px 17px 0 0;overflow:hidden;background:#244e49}.art span{font-family:Space;font-size:72px;transition:transform 450ms var(--ease)}.panel:hover .art span{transform:rotate(-8deg) scale(1.1)}.purple .art{background:#3a3156;color:#c09bff}.gold .art{background:#4b422b;color:#ffd78d}.cyan .art{color:#45dfff}.result{display:grid;grid-template-columns:50px 1fr auto;gap:20px;align-items:center;border-bottom:1px solid var(--line);padding:20px 0}.book{width:42px;height:60px;background:#275444;border-radius:3px 9px 9px 3px;border-left:4px solid #58c99a;display:grid;place-items:center;font-family:Space}.road{padding-left:25px;border-left:1px solid #427057;margin-left:9px}.road article{position:relative;margin:0 0 25px}.road article:before{content:'';position:absolute;left:-31px;top:6px;width:10px;height:10px;background:var(--mint);border-radius:50%}.comment{padding:22px 0;border-bottom:1px solid var(--line)}.comment p{margin:15px 0}.board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.board .panel{margin-top:15px;padding:18px}.vote{border:1px solid var(--line);background:transparent;border-radius:8px;padding:8px 12px}.toggle{width:48px;height:27px;padding:3px;background:#294039;border:1px solid var(--line);border-radius:30px}.toggle:before{content:'';display:block;width:19px;height:19px;background:var(--muted);border-radius:50%;transition:transform 180ms var(--ease)}.toggle[aria-pressed=true]{background:#246c46}.toggle[aria-pressed=true]:before{transform:translateX(20px);background:var(--mint)}.about-symbol{font-family:Space;font-size:clamp(58px,9vw,120px);letter-spacing:-5px;color:var(--mint);text-align:center;margin:25px 0 40px}.table{width:100%;border-collapse:collapse;font-size:12px}.table td,.table th{text-align:left;padding:16px 10px;border-bottom:1px solid var(--line)}.table th{color:var(--muted);font-weight:400}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);opacity:0;background:var(--mint);color:#062519;padding:14px 22px;border-radius:12px;pointer-events:none;transition:all 220ms var(--ease);z-index:30;max-width:90vw}.toast.show{opacity:1;transform:translate(-50%,0)}.foot{font-size:11px;color:var(--muted);padding-top:20px;border-top:1px solid var(--line)}details{margin-top:20px}summary{cursor:pointer;color:var(--mint)}details p{font-size:12px;max-width:850px}[hidden]{display:none!important}dialog{background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:18px;max-width:520px;width:calc(100% - 36px);padding:28px}dialog::backdrop{background:#020c09bb}button:disabled{cursor:default;opacity:.65}.light{--bg:#e8f3eb;--panel:#fff;--text:#123326;--muted:#486956;--line:#b6d1c2}.light .hero,.light .composer,.light .reply,.light .bubble{color:#edf6f1}.light .lab{color:#edf6f1}.light .ring-inner{background:#e8f3eb}.light .podium,.light .node{color:#edf6f1}.reduced *,.reduced *:before,.reduced *:after{animation:none!important;transition:none!important}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}@media(max-width:1100px){main{padding:25px}.layout{grid-template-columns:200px minmax(0,1fr)}.split{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.lab{padding:10px 14px;flex-wrap:wrap}.layout{display:block}aside{position:relative;top:0;height:auto;padding:18px 14px;border-right:0;border-bottom:1px solid var(--line)}.brand{margin:0 0 15px}.group{display:none}nav{display:flex;gap:6px;overflow-x:auto}nav a{white-space:nowrap;flex-shrink:0;margin:0;padding:10px}.nav-icon{display:none}main{padding:24px 18px}.topline{margin-bottom:28px}.grid,.two,.board,.notes{grid-template-columns:1fr}.week{gap:4px}.day{padding:12px 3px}.day strong{font-size:20px}.panel{padding:20px}.art{margin:-20px -20px 20px}.ring{width:230px;height:230px}.result{grid-template-columns:40px 1fr;gap:12px}.result button{grid-column:2;width:max-content}.table td,.table th{padding:13px 5px}.topline>.tag{display:none}.intro p{font-size:14px}.map{min-height:310px}.node{font-size:11px;padding:10px}.foot{line-height:1.7}h1{letter-spacing:-1px}}
'''
sections=[]; nav=[]
def btn(text,attrs='',cls='primary'):return f'<button class="{cls}" {attrs}>{text}</button>'
def task(title,time):return f'<label class="task"><input type="checkbox"><span>{title}</span><em>{time}</em></label>'
def panel(title,body):return f'<div class="panel"><h3>{title}</h3>{body}</div>'
def add(id,label,icon,title,desc,body,gain,loss,new='Composição e interação propostas; conteúdo de exemplo.'):
 nav.append((id,label,icon))
 sections.append(f'<section class="concept" id="{id}" aria-labelledby="title-{id}"><div class="intro"><span class="eyebrow">{label} · conceito de interface</span><h1 id="title-{id}">{title}</h1><p>{desc}</p></div>{body}<div class="notes"><div><p><b>Decisão de design.</b> {gain}</p><p><b>Trade-off.</b> {loss}</p></div><div><p><b>Proposta nova.</b> {new}</p><p><b>Esforço estimado.</b> {"Alto" if id in ["mine","games","admin"] else "Médio"} · sem integração.</p></div></div></section>')
add('home','Início','⌂','Seu próximo passo,<br>em primeiro plano.','Uma mesa de estudo que começa pela ação mais útil e deixa suas matérias ao alcance.',f'<div class="split"><div class="panel hero"><span class="eyebrow">Continuar de onde parou</span><h2>Entender antes de memorizar.</h2><p>Biologia · Divisão celular</p><p>Retome seu material e prepare uma revisão de 20 minutos.</p>{btn("Abrir caderno →","data-go=subject")}<div class="track"><span style="width:60%"></span></div><p class="small" style="margin-top:15px">Exemplo · 6 de 10 materiais</p></div><div class="panel map"><div class="core">Seu estudo</div><button class="node" data-go="subject">Biologia ↗</button><button class="node" data-go="subject">Matemática ↗</button><button class="node" data-go="plan">Seu plano ↗</button><button class="node" data-go="mine">Mine ↗</button></div></div><div class="two" style="margin-top:20px">{panel("O que pede atenção",task("Revisar mitose","Hoje")+task("Resolver 5 equações","Hoje"))}{panel("Proteja um tempo para aprender","<p>Uma sessão curta também conta.</p>"+btn("Entrar em foco →","data-go=foco"))}</div>','Continuidade no centro; matérias em um mapa de atalhos.','O mapa ocupa mais espaço que uma lista compacta.','Mapa de navegação; não representa relações calculadas pela IA.')
add('agenda','Agenda','▦','Uma semana.<br>Prioridades claras.','Selecione um dia para ver as entregas. Marque uma tarefa para concluí-la.', '<div class="week">'+''.join(f'<button class="day {"selected" if i==0 else ""}" data-day="{i}" aria-pressed="{"true" if i==0 else "false"}"><small>{d}</small><strong>{i+5}</strong><span class="dot"></span></button>' for i,d in enumerate(['SEG','TER','QUA','QUI','SEX','SÁB','DOM']))+'</div><div class="split">'+panel('<span id="day-title">Segunda-feira</span>','<p class="small">Semana ilustrativa · 5–11 outubro de 2026</p><div id="day-tasks">'+task('Revisar mitose','09:00')+task('Resolver 5 equações','14:00')+'</div>')+panel('Seu material está perto','<span class="tag">Biologia</span><h2 style="margin-top:20px">Divisão celular</h2><p>Abra o caderno antes de começar uma revisão.</p>'+btn('Ver caderno →','data-go=subject'))+'</div>','Semana e contexto aparecem juntos; a seleção preserva a orientação.','A visão semanal exige navegação para períodos maiores.','Painel de acesso ao caderno; agenda e conclusão já existem no produto.')
add('foco','Foco','◷','Menos distração.<br>Mais presença.','O cronômetro ganha o centro. Sua intenção permanece ao lado, sem competir com a sessão.',f"""<div class="split"><div class="panel center"><div class="seg" style="justify-content:center">{btn("25 minutos","data-duration=25","quiet selected")}{btn("50 minutos","data-duration=50","quiet")}</div><div class="ring" id="focus-ring"><div class="ring-inner"><span class="eyebrow">Biologia · foco</span><span class="timer" id="timer">25:00</span><span class="muted small" id="timer-state">Pronto para começar</span></div></div><div class="row" style="justify-content:center">{btn("Iniciar sessão","id=start-focus")}{btn("Reiniciar","id=reset-focus","quiet")}</div></div>{panel("Uma intenção para esta sessão",'<label for="focus-intent" class="small muted">O que você quer entender?</label><input id="focus-intent" value="Diferenças entre mitose e meiose" style="margin-top:12px"><p style="margin-top:25px">Leia um trecho. Feche o material. Explique com suas palavras.</p><span class="tag">Sessão demonstrativa · não salva minutos</span>')}</div>""",'O anel traduz o tempo; início e pausa têm feedback imediato.','A composição imersiva reduz informações simultâneas.')
add('progress','Progresso','↗','Veja o ritmo.<br>Reconheça o avanço.','A evolução começa pela constância, depois chega a cada matéria.','<div class="split"><div class="panel"><h3>Tempo de estudo</h3><span class="tag">Dados fictícios</span><div class="seg">'+btn('Semana','data-period=week','quiet selected')+btn('Mês','data-period=month','quiet')+'</div><div class="bars">'+''.join(f'<div class="bar-col"><span class="bar" style="height:{v}%" data-bar="{v}"></span><small>{d}</small></div>' for d,v in zip(['S','T','Q','Q','S','S','D'],[30,65,45,82,60,35,70]))+'</div><p id="period-caption" class="small" style="margin:20px 0 0">Semana de exemplo · 4h 20min</p></div>'+panel('Aprendizado por matéria',''.join(f'<div style="margin-bottom:25px"><div class="row"><span>{n}</span><b class="mint">{v}%</b></div><div class="track"><span style="width:{v}%"></span></div></div>' for n,v in [('Biologia',72),('Matemática',48),('História',61)]))+'</div><div class="panel" style="margin-top:20px"><h3>Pequenos encontros, todos os dias.</h3><p class="small">Consistência ilustrativa · 8 semanas</p><div class="heatmap">'+''.join('<span></span>' for _ in range(56))+'</div></div>','Gráficos mudam de período preservando o espaço de leitura.','O histórico detalhado fica em segundo plano.','Gráficos propostos; valores não são diagnósticos reais.')
add('ranking','Ranking','♜','Uma comunidade<br>que avança junto.','O pódio celebra o grupo. Sua posição continua legível longe dos primeiros lugares.','<div class="split"><div class="panel"><span class="tag">Temporada demonstrativa</span><div class="podium">'+''.join(f'<div><div class="avatar">{n[0]}</div><h3>{n}</h3><small>{xp} XP</small><span class="num">{pos}</span></div>' for n,xp,pos in [('Lia','2.180',2),('Ravi','2.420',1),('Noa','1.960',3)])+'</div></div>'+panel('Seu percurso','<span class="num mint">12º</span><p>1.240 XP · perfil fictício</p><div class="track"><span style="width:68%"></span></div><p style="margin-top:18px">Seu próximo avanço começa com mais uma revisão.</p>'+btn('Praticar com a Mine →','data-go=games'))+'</div>','Celebração do grupo com acesso direto à prática.','O pódio ocupa mais espaço que uma classificação compacta.')
add('mine','Mine','✧','Uma conversa.<br>Um caminho para entender.','Contexto, explicação e próximos passos ocupam lugares distintos.', '<div class="split"><div class="panel"><div class="row"><span class="tag">Contexto · Biologia</span><span class="small muted">Demonstração local</span></div><div class="chat" id="chat"><div class="bubble">Como diferenciar mitose de meiose?</div><div class="reply"><b class="mint">Mine</b><br>Na mitose, uma célula origina duas células com o mesmo número de cromossomos. Na meiose, duas divisões originam quatro células com metade desse número.<br><span class="small muted">Resposta de exemplo escrita para este conceito.</span></div></div><form class="composer" id="chat-form"><textarea aria-label="Mensagem para a Mine" placeholder="Pergunte sobre sua matéria…" required></textarea>'+btn('Enviar ↗','type=submit')+'</form></div>'+panel('Leve a explicação adiante','<p>Transforme o que acabou de aprender em revisão.</p><div class="seg">'+btn('Testar entendimento','data-demo=quiz','quiet')+btn('Ver flashcard','data-demo=flashcard','quiet')+btn('Abrir caderno','data-go=subject','quiet')+'</div><p class="small">Respostas e exercícios predefinidos. Sem conexão com IA.</p>')+'</div>','Conversa contextual com painel de prática e entrada animada de mensagens.','O painel lateral precisa ser empilhado no celular.','Painel de próximos passos; quiz e flashcards já existem, aqui são amostras locais.')
add('games','Games com a Mine','◇','Escolha o desafio.<br>Aprenda jogando.','Cada jogo comunica seu raciocínio antes de começar. Experimente uma rodada.','<div class="grid">'+''.join(f'<article class="panel {tone}"><div class="art"><span>{symbol}</span></div><span class="eyebrow">{skill}</span><h3>{name}</h3><p>{desc}</p>'+btn('Experimentar rodada →',f'data-game="{i}"')+'</article>' for i,(name,skill,desc,symbol,tone) in enumerate([('Nexo Vivo','Conexões','Encontre a ligação entre ideias.','⌘','cyan'),('Forja de Sequências','Lógica','Descubra o próximo padrão.','⋈','purple'),('Minerva Aventuras','Exploração','Responda e avance no percurso.','△','gold')]))+'</div><div class="panel" id="game-stage" style="margin-top:20px"><h3>Uma rodada para conhecer.</h3><p>Selecione um jogo acima.</p></div>','Galeria com símbolos próprios e desafios jogáveis no mesmo contexto.','Artes exclusivas exigem mais manutenção.','Rodadas ilustrativas, sem XP real nem geração por IA.')
add('search','Busca','⌕','Encontre.<br>Explore. Guarde.','Uma biblioteca que revela o conteúdo antes de você sair da busca.','<div class="panel"><label for="search-input" class="eyebrow">Pesquisar nos exemplos</label><input id="search-input" placeholder="Tente biologia, equações ou história"><div class="seg">'+''.join(btn(t,f'data-filter="{v}"','quiet'+(' selected' if v=='all' else '')) for t,v in [('Todos','all'),('Materiais','material'),('Livros','book'),('Artigos','article')])+'</div><div id="search-results">'+''.join(f'<article class="result" data-kind="{kind}" data-text="{title.lower()}"><div class="book">{letter}</div><div><span class="tag">{type}</span><h3 style="margin:10px 0 4px">{title}</h3><p class="small" style="margin:0">{desc}</p></div>'+btn('Prévia','data-preview="'+title+'"','quiet')+'</article>' for title,kind,type,letter,desc in [('Divisão celular: biologia em resumo','material','Material','B','Seu caderno · exemplo'),('Equações e funções','book','Livro','M','Resultado ilustrativo'),('Aprender história com fontes','article','Artigo','H','Resultado ilustrativo')])+'</div><p id="search-empty" hidden>Nenhum exemplo encontrado. Tente “biologia”.</p></div>','Filtros e prévia reduzem idas e voltas entre busca e caderno.','A prévia precisa cobrir formatos diferentes.','Busca demonstrativa; Open Library e Crossref não são consultados aqui.')
add('plan','Plano de estudos','▤','Um plano que cabe<br>na sua semana.','Ajuste o ritmo e veja a distribuição mudar. O resultado acompanha suas escolhas.','<div class="split"><div class="panel form"><h3>O que vamos estudar?</h3><label class="task"><input type="checkbox" checked data-plan-subject="Biologia"><span>Biologia</span></label><label class="task"><input type="checkbox" checked data-plan-subject="Matemática"><span>Matemática</span></label><label for="plan-days">Dias até a prova: <b id="days-value">14</b></label><input type="range" id="plan-days" min="3" max="30" value="14"><label for="plan-pace">Ritmo</label><select id="plan-pace"><option value="20">Leve · 20 minutos por dia</option><option value="40" selected>Normal · 40 minutos por dia</option><option value="60">Intenso · 60 minutos por dia</option></select><p class="small" style="margin-top:25px">Distribuição local, sem solicitação à IA.</p></div><div class="panel"><span class="eyebrow">Prévia viva</span><h3 id="plan-summary">14 dias · 40 min por dia</h3><div class="road" id="plan-road" style="margin-top:25px"></div>'+btn('Confirmar plano de exemplo','data-toast="Plano confirmado apenas nesta demonstração."')+'</div></div>','Cronograma e configuração juntos com atualização contínua.','É preciso distinguir claramente prévia de plano salvo.','Prévia automática; criação manual e com Mine já existem no produto.')
add('comments','Comentários','☏','Aprender também<br>é trocar experiências.','Leitura confortável e respostas em contexto. Adicione um comentário local.','<div class="split"><div class="panel" id="comments-list">'+''.join(f'<article class="comment"><b>{name} · personagem fictício</b><p>{text}</p>'+btn('Responder',f'data-reply="{name}"','quiet')+'</article>' for name,text in [('Lia','Fazer uma revisão curta depois da aula me ajudou a lembrar os conceitos.'),('Ravi','Gostei de testar as conexões entre os assuntos antes de voltar ao material.')])+'</div><div class="panel"><h3>Sua experiência pode ajudar.</h3><form id="comment-form" class="form"><label for="comment-text">Comentário de exemplo</label><textarea class="field" id="comment-text" rows="5" maxlength="700" required placeholder="O que funcionou nos seus estudos?"></textarea><div style="margin-top:16px">'+btn('Adicionar comentário','type=submit')+'</div></form><p class="small" style="margin-top:18px">Não é publicado. Fica somente nesta página aberta.</p></div></div>','Editor ao lado da conversa com confirmação visual ao adicionar conteúdo.','Respostas contextualizadas precisam de regras de moderação.','Resposta contextual é proposta nova; comentários são locais.')
add('suggestions','Sugestões','✳','Ideias com espaço<br>para evoluir.','Um quadro mostra o caminho das sugestões. Experimente apoiar uma ideia.','<div class="board">'+''.join(f'<div><span class="eyebrow">{status}</span><article class="panel"><span class="tag">{cat}</span><h3 style="margin-top:20px">{title}</h3><p>{desc}</p><button class="vote" aria-pressed="false" data-votes="{votes}">↑ {votes} · Apoiar</button></article></div>' for status,cat,title,desc,votes in [('Novas','Ideia','Revisão em dupla','Praticar com outra pessoa.',12),('Em análise','Melhoria','Agenda mais compacta','Ver mais tarefas com leitura confortável.',8),('Concluídas','Exemplo de status','Contraste nos controles','Retorno claro sobre melhorias.',21)])+'</div><div class="panel" style="margin-top:20px"><h3>O que gostaria de melhorar?</h3><form id="suggestion-form" class="composer"><textarea required aria-label="Nova sugestão" maxlength="700" placeholder="Descreva uma ideia…"></textarea>'+btn('Adicionar ideia','type=submit')+'</form></div>','Quadro por estado e apoio com feedback imediato.','Popularidade pode pesar mais que o impacto de uma ideia.','Votação e quadro são propostas novas; estados ilustrativos.')
add('about','Sobre','ⓘ','Conhecimento<br>em movimento.','Uma apresentação conectada ao que você pode fazer na Minerva.','<div class="panel hero"><div class="about-symbol">MINERVA</div><div class="two"><h2>Estudar, praticar e acompanhar seu percurso.</h2><p>Organize materiais. Converse com a Mine. Coloque seu conhecimento à prova. A Minerva reúne essas etapas em um mesmo espaço.</p></div></div><div class="grid" style="margin-top:20px">'+''.join(panel(t,'<p>'+d+'</p>'+btn(a,'data-go='+id,'quiet')) for t,d,a,id in [('Organizar','Transforme entregas em uma rotina possível.','Conhecer a agenda →','agenda'),('Entender','Use a conversa para aprofundar uma ideia.','Conhecer a Mine →','mine'),('Praticar','Explore desafios de raciocínio e conexões.','Conhecer os jogos →','games')])+'</div>','A apresentação vira uma jornada de ações reconhecíveis.','Menos espaço inicial para detalhes institucionais.')
add('perfil','Perfil e ajustes','⚙','Seu espaço.<br>Do seu jeito.','Preferências com prévia imediata de tema e movimento.','<div class="split"><div class="panel form"><div class="avatar" style="width:72px;height:72px;font-size:28px">E</div><h3 class="center" id="profile-name">Estudante exemplo</h3><label for="display-name">Nome de exibição</label><input id="display-name" value="Estudante exemplo" maxlength="45"><label for="bio">Sobre você</label><textarea id="bio" class="field" rows="3">Aprendendo um pouco a cada dia.</textarea><div style="margin-top:18px">'+btn('Salvar perfil de exemplo','data-save-profile')+'</div></div><div class="panel"><h3>Como prefere estudar?</h3><div class="task row"><span>Tema claro</span><button class="toggle" id="theme-toggle" aria-label="Tema claro" aria-pressed="false"></button></div><div class="task row"><span>Reduzir movimento</span><button class="toggle" id="motion-toggle" aria-label="Reduzir movimento" aria-pressed="false"></button></div><p class="small" style="margin-top:25px">A prévia muda somente este protótipo. O movimento reduzido do dispositivo também é respeitado.</p><span class="tag">Conta fictícia · sem persistência</span></div></div>','Preferências ficam concretas porque alteram a prévia.','Tema claro pede contraste consistente em gráficos e arte.')
add('admin','Admin','⬡','Visão geral.<br>Ação com contexto.','Um console que abre detalhes preservando os sinais do sistema.','<div class="grid">'+panel('Estudantes','<span class="num">128</span><p class="small">Contagem ilustrativa</p>')+panel('Sugestões novas','<span class="num mint">8</span><p class="small">Fila demonstrativa</p>')+panel('Sistema','<span class="tag">Status de exemplo</span><p style="margin-top:20px">Operacional</p>')+'</div><div class="split" style="margin-top:20px"><div class="panel"><h3>Contas de exemplo</h3><table class="table"><thead><tr><th>Estudante</th><th>Materiais</th><th>Detalhes</th></tr></thead><tbody>'+''.join(f'<tr><td>{name}</td><td>{n}</td><td>'+btn('Abrir',f'data-admin="{name}"','quiet')+'</td></tr>' for name,n in [('Lia',14),('Ravi',21),('Noa',8)])+'</tbody></table></div><div class="panel" id="admin-detail"><span class="eyebrow">Painel contextual</span><h3>Escolha uma conta</h3><p>O detalhe aparece aqui, mantendo a lista visível.</p><p class="small">Sem acesso a dados ou ações administrativas reais.</p></div></div>','Lista e detalhe reduzem trocas de tela; animação comunica seleção.','A densidade exige hierarquia e autorização por ação.','Console visual com contas fictícias, sem alterar permissões.')
add('subject','Matéria · tela interna','▱','Um caderno.<br>Muitas formas de aprender.','Leitura, anotações e revisão compartilham o contexto da matéria.','<div class="seg">'+''.join(btn(t,'data-notebook='+id,'quiet'+(' selected' if id=='material' else '')) for t,id in [('Material','material'),('Anotações','notes'),('Revisão','review')])+'</div><div class="split"><div class="panel" id="notebook"><span class="eyebrow">Biologia · exemplo</span><h2>Divisão celular</h2><p>A divisão celular permite o crescimento e a renovação dos tecidos. Na mitose, o material genético é distribuído entre duas células-filhas.</p><h3>Uma pergunta para levar</h3><p>Por que o DNA é replicado antes da divisão?</p></div>'+panel('Seu caderno de Biologia','<p class="small">6 de 10 materiais estudados · dados fictícios</p><div class="track"><span style="width:60%"></span></div><div class="seg">'+btn('Perguntar à Mine →','data-go=mine')+btn('Estudar com foco →','data-go=foco','quiet')+'</div>')+'</div>','A matéria permanece como referência ao alternar leitura e revisão.','Anotações precisam de proteção contra perda ao navegar.','Rascunho local; a tela complementa as 14 abas.')
groups=[('Estudo',nav[:5]),('Inteligência',nav[5:9]),('Comunidade',nav[9:11]),('Conta',nav[11:14]),('Tela interna',nav[14:])]
menu=''.join(f'<div class="group">{g}</div>'+''.join(f'<a href="#{id}"><span class="nav-icon" aria-hidden="true">{icon}</span>{label}</a>' for id,label,icon in items) for g,items in groups)
js=(out/'interactions.js').read_text(encoding='utf-8')
logo=base64.b64encode((root/'assets/app_logo.png').read_bytes()).decode()
html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Minerva · Conceitos de todas as abas</title><style>'+f'@font-face{{font-family:Jakarta;src:url(data:font/ttf;base64,{font("plus_jakarta_sans_regular.ttf")})}}@font-face{{font-family:Space;src:url(data:font/ttf;base64,{font("space_grotesk_semibold.ttf")});font-weight:700}}'+css+'</style></head><body><header class="lab"><div><strong>MINERVA / LAB DE CONCEITOS</strong> · 14 abas + caderno · 29 set 2026</div><button class="quiet" id="lab-motion" aria-pressed="false">Reduzir movimento</button></header><div class="layout"><aside><div class="brand"><img src="data:image/png;base64,'+logo+'" alt="">Minerva</div><nav aria-label="Abas do protótipo">'+menu+'</nav></aside><main><div class="topline"><span>Minerva / <span id="current-label">Início</span></span><span class="tag">Protótipo interativo · dados fictícios</span></div>'+''.join(sections)+'''<footer class="foot">Conceitos de design · identidade e navegação observadas no código local. Nomes, números e conteúdos fictícios. Interações locais, sem publicação ou alteração da conta.<details><summary>Direção recomendada e critérios</summary><p>Recomendo a continuidade contextual: uma pergunta principal por aba, uma ação dominante e acesso ao contexto. O trade-off é o espaço ocupado pelos painéis no desktop, que passam a ser empilhados no celular.</p><p>Identidade observada: verde Minerva #39f59a, Plus Jakarta Sans e Space Grotesk, navegação por Estudo, Inteligência, Comunidade e Conta. Proposta: base #0b1413 e superfícies #142321 com ciano e violeta nos jogos. O mapa de atalhos é a assinatura visual.</p><p>Diagnóstico: o produto já tem gráficos, foco, jogos e ferramentas de estudo com a Mine. Cada conceito reorganiza funções existentes em torno de uma ação. Novas propostas explícitas: mapa de navegação, painel de próximos passos, votação, respostas em contexto e prévia contínua do plano.</p><p>Movimento calmo e responsivo: feedback 160 ms, detalhes 280 ms e páginas 440 ms, curva cubic-bezier(.2,0,0,1). Movimento reduzido respeitado. O anel de foco comunica tempo, o mapa respira discretamente e a arte dos jogos responde ao ponteiro.</p><p>Fontes: src/main.tsx (abas, grupos, telas e estados), src/index.css (cores e fontes), README.md (integrações). Esforços são estimativas visuais. APIs, permissões e persistência não são verificadas neste protótipo.</p></details></footer></main></div><dialog id="preview-dialog" aria-labelledby="modal-title"><h2 id="modal-title">Prévia</h2><p id="modal-text"></p><button class="primary" id="close-dialog">Fechar prévia</button></dialog><div class="toast" id="toast" role="status" aria-live="polite"></div><script>'''+js+'</script></body></html>'
(out/'minerva-conceitos.html').write_text(html,encoding='utf-8')
print('Criado: 15 telas em',out/'minerva-conceitos.html')
